  const returnFocus=useRef<HTMLElement|null>(null),langRef=useRef<HTMLDivElement>(null),tabsRef=useRef<HTMLDivElement>(null),[langPill,setLangPill]=useState<{left:number;width:number}|null>(null),[tabPill,setTabPill]=useState<{left:number;top:number;width:number;height:number}|null>(null);
