  useEffect(()=>{if(!modalOpen)return;const frame=requestAnimationFrame(()=>document.querySelector<HTMLElement>('[role="dialog"] .modal-close')?.focus());return()=>cancelAnimationFrame(frame)},[modalOpen,profile,download,preview]);
  useEffect(()=>{if(!mobileMenu)return;const closeMenu=(event:KeyboardEvent)=>{if(event.key==="Escape"){event.preventDefault();setMobileMenu(false);requestAnimationFrame(()=>document.querySelector<HTMLElement>(".menu-button")?.focus())}};window.addEventListener("keydown",closeMenu);return()=>window.removeEventListener("keydown",closeMenu)},[mobileMenu]);
  useEffect(()=>{const nodes=Array.from(document.querySelectorAll<HTMLElement>(".reveal"));if(reducedMotion()||!("IntersectionObserver" in window)||typeof IntersectionObserver==="undefined"){nodes.forEach(n=>n.classList.add("is-visible"));return}const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add("is-visible");observer.unobserve(entry.target)}}),{threshold:.12,rootMargin:"0px 0px -7%"});nodes.forEach(node=>observer.observe(node));return()=>observer.disconnect()},[]);
  // The hero tells the app's story in three screens and moves on by itself.
